window.UDM_PROGRAMS["my-seem"]=(window.UDM_PROGRAMS["my-seem"]||"")+"\";\nconst alphabet='А Б В Г Д Е Ё Ж Ӝ З Ӟ И Ӥ Й К Л М Н О Ӧ П Р С Т У Ф Х Ц Ч Ӵ Ш Щ Ъ Ы Ь Э Ю Я'.split(' '), $=id=>document.getElementById(id), storageKey='my-seem-field-v05';\n// Музыка запускается только после действия пользователя — так требуют браузеры.\nconst music=$('krezMusic'), musicButton=$('musicToggle'), volume=$('musicVolume');\nlet musicPlaying=false;\ntry{const v=localStorage.getItem('my-seem-music-volume');if(v!==null)volume.value=Math.max(0,Math.min(100,Number(v)||0))}catch(e){}\nmusic.volume=Number(volume.value)/100;\nfunction syncMusicButton(){musicButton.textContent=musicPlaying?'♫ Выключить музыку':'♫ Включить музыку';musicButton.setAttribute('aria-pressed',String(musicPlaying))}\nmusicButton.addEventListener('click',async()=>{if(musicPlaying){music.pause();musicPlaying=false;syncMusicButton();return}try{await music.play();musicPlaying=true;syncMusicButton()}catch(e){musicPlaying=false;syncMusicButton();alert('Не удалось воспроизвести музыку. Попробуй включить музыку ещё раз после нажатия кнопки.')}});\nvolume.addEventListener('input',()=>{music.volume=Number(volume.value)/100;try{localStorage.setItem('my-seem-music-volume',volume.value)}catch(e){}});\n\nlet progress={};try{const saved=JSON.parse(localStorage.getItem(storageKey)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))progress=saved}catch(e){}\nconst MAX_TRIES=3;const scoreStorageKey='my-seem-scores-v1';let scoreState={results:{},support:{}};\ntry{const v=JSON.parse(localStorage.getItem(scoreStorageKey)||'null');if(v&&v.results&&typeof v.results==='object'&&!Array.isArray(v.results)&&v.support&&typeof v.support==='object'&&!Array.isArray(v.support))scoreState=v}catch(e){}\nlet revealed=new Set(),hintUsed=false;\nfunction wordKey(){return active.id+':'+idx}\nfunction getSupport(){const key=wordKey();let v=scoreState.support[key];if(!v||typeof v!=='object')v=scoreState.support[key]={hint:false,revealed:[]};v.hint=!!v.hint;if(!Array.isArray(v.revealed))v.revealed=[];v.revealed=[...new Set(v.revealed.filter(i=>Number.isInteger(i)&&i>=0&&i<Array.from(active.words[idx][1]).length))];return v}\nfunction publishSeemScore(){window.udmSeemSnapshot={progress,results:scoreState.results};if(window.parent!==window)window.parent.postMessage({type:'udm-seem-snapshot',progress,results:scoreState.results},'*')}function saveScores(){try{localStorage.setItem(scoreStorageKey,JSON.stringify(scoreState))}catch(e){console.warn('Сохранение баллов недоступно',e)}publishSeemScore()}\nfunction potentialTenths(){return Math.max(0,10-(hintUsed?5:0)-revealed.size)}\nfunction formatPoints(n){return (n/10).toLocaleString('ru-RU',{maximumFractionDigits:1})}\nfunction scoreSummary(){const valid=Object.entries(scoreState.results).filter(([k,v])=>{const [c,i]=k.split(':');const cat=categories.find(t=>t.id===c);return cat&&completed(cat).includes(Number(i))&&v&&Number.isInteger(v.tenths)&&v.tenths>=0&&v.tenths<=10});const total=valid.reduce((n,[,v])=>n+v.tenths,0);const old=categories.reduce((n,c)=>n+completed(c).length,0)-valid.length;$('scoreSummary').textContent=`Баллы: ${formatPoints(total)} / 50`+(old>0?` · Ранее освоено без оценки: ${old}. Старые слова не оценены задним числом.`:'');return total}\nfunction renderPoints(){const fee=(hintUsed?5:0)+revealed.size;$('wordPoints').textContent=`За слово: ${formatPoints(potentialTenths())} из 1 балла`+(fee?` · Подсказка: ${hintUsed?'−0,5':'не использована'} · Открыто букв: ${revealed.size} (−${formatPoints(revealed.size)})`:' · Без подсказок');}\nfunction illustrate(ru){const art=WORD_ART[ru],box=$('wordIllustration');box.replaceChildren();if(art.src){const img=new Image();img.src=art.src;img.alt=ru;box.append(img)}else{const div=document.createElement('div');div.className='atlas-art';div.setAttribute('role','img');div.setAttribute('aria-label',ru);div.style.backgroundImage='url(\"'+WORD_ATLAS+'\")';div.style.backgroundPosition=(art.sprite%4)*100/3+'% '+Math.floor(art.sprite/4)*100+'%';box.append(div);const im=new Image();im.onload=()=>div.style.aspectRatio=im.naturalWidth/(2*im.naturalHeight);im.src=WORD_ATLAS;}}\n\nfunction completed(cat){return Array.isArray(progress[cat.id])?progress[cat.id].filter(n=>Number.isInteger(n)&&n>=0&&n<10):[]}\nfunction save(){try{localStorage.setItem(storageKey,JSON.stringify(progress))}catch(e){console.warn('Сохранение недоступно',e)}}\nfunction show(id){['welcome','mapScreen','game'].forEach(x=>$(x).classList.toggle('hidden',x!==id));window.scrollTo({top:0,behavior:'smooth'})}\nfunction stalks(id,ratio){const h=Math.round(10+ratio*105);$(id).innerHTML=Array.from({length:15},(_,i)=>`<div class=\"stalk\" style=\"--h:${Math.max(5,h+(i%4)*3-5)}px;--delay:${(i%6)*-.45}s;--ear:${ratio>.65?1:0}\"></div>`).join('')}\nstalks('welcomeStalks',1);let active=null,idx=-1,guessed=new Set(),wrong=0,finished=false;\nfunction map(){let total=0;$('map').innerHTML='';categories.forEach(cat=>{const n=completed(cat).length;total+=n;const button=document.createElement('button');button.type='button';button.className='plot';button.style.setProperty('--fill',`${n*10}%`);button.style.setProperty('--opacity',n===10?'1':'0');button.innerHTML=`<span class=\"plotname\">${cat.ru}</span><span class=\"udm\">${cat.ud}</span><span class=\"count\">${n}/10 ${n===10?'✓':''}</span>`;button.setAttribute('aria-label',`${cat.ru}, ${n} из 10 слов`);button.onclick=()=>openCategory(cat);$('map').append(button)});$('overallBar').style.setProperty('--width',`${total*2}%`);$('overallText').textContent=`${total} из 50 слов освоено`;$('harvest').classList.toggle('hidden',total!==50);scoreSummary();show('mapScreen')}\nfunction openCategory(cat){active=cat;const next=cat.words.findIndex((_,i)=>!completed(cat).includes(i));if(next===-1){$('harvest').textContent=`🌾 Участок «${cat.ru}» уже созрел! Можешь выбрать другой.`;map();return}loadWord(next);show('game')}\nfunction loadWord(i){idx=i;guessed=new Set();wrong=0;finished=false;const support=getSupport();revealed=new Set(support.revealed);hintUsed=support.hint;$('hint').textContent=hintUsed?`👩 По-русски: «${active.words[idx][0]}».`:'👩 Подсказка: можно узнать значение слова.';$('hintButton').disabled=hintUsed;$('letterButton').disabled=false;$('nextButton').classList.add('hidden');$('message').textContent='';illustrate(active.words[idx][0]);render()}\nfunction render(){const [ru,ud]=active.words[idx],letters=Array.from(ud.toLocaleUpperCase('ru-RU'));const known=(ch,i)=>guessed.has(ch)||revealed.has(i);$('gameCategory').textContent=active.ru;$('tries').textContent=`❤️ ${MAX_TRIES-wrong} из ${MAX_TRIES}`;$('wordCount').textContent=`Освоено ${completed(active).length} из 10 · угадай слово`;$('categoryBar').style.setProperty('--width',`${completed(active).length*10}%`);$('word').innerHTML=letters.map((ch,i)=>`<span class=\"letter${revealed.has(i)?' revealed':''}\">${known(ch,i)||finished&&wrong>=MAX_TRIES?ch:' '}</span>`).join('');const ratio=letters.filter(known).length/letters.length;stalks('gameStalks',ratio);$('keyboard').innerHTML='';alphabet.forEach(ch=>{const b=document.createElement('button');b.className='key';b.textContent=ch;b.disabled=guessed.has(ch)||finished;b.onclick=()=>guess(ch);$('keyboard').append(b)});renderPoints();if(!finished&&(letters.every(known)||wrong>=MAX_TRIES)){finished=true;if(wrong<MAX_TRIES){const done=new Set(completed(active));done.add(idx);progress[active.id]=[...done];if(!scoreState.results[wordKey()])scoreState.results[wordKey()]={tenths:potentialTenths(),hint:hintUsed,revealed:revealed.size};save();saveScores();$('message').textContent=`🌾 Верно! ${ud} — ${ru}. +${formatPoints(scoreState.results[wordKey()].tenths)} ${scoreState.results[wordKey()].tenths===10?'балл':scoreState.results[wordKey()].tenths===0?'баллов':'балла'}`;stalks('gameStalks',1)}else{$('message').textContent=`Ответ: ${ud} — ${ru}. Попробуй ещё раз!`}$('keyboard').querySelectorAll('button').forEach(b=>b.disabled=true);$('hintButton').disabled=true;$('letterButton').disabled=true;const left=active.words.findIndex((_,i)=>!completed(active).includes(i));$('nextButton').textContent=left===-1?'🌾 Участок созрел! →':wrong>=MAX_TRIES?'Попробовать снова →':'Следующее слово →';$('nextButton').classList.remove('hidden')}}\nfunction guess(ch){if(finished||guessed.has(ch))return;guessed.add(ch);if(!active.words[idx][1].toLocaleUpperCase('ru-RU').includes(ch))wrong++;render()}\n$('hintButton').onclick=()=>{if(finished||hintUsed)return;hintUsed=true;getSupport().hint=true;saveScores();$('hint').textContent=`👩 По-русски: «${active.words[idx][0]}».`;$('hintButton').disabled=true;renderPoints()};\n$('letterButton').onclick=()=>{if(finished)return;const letters=Array.from(active.words[idx][1].toLocaleUpperCase('ru-RU'));const i=letters.findIndex((ch,i)=>!guessed.has(ch)&&!revealed.has(i));if(i>=0){revealed.add(i);getSupport().revealed=[...revealed];saveScores();$('hint').textContent=(hintUsed?`👩 По-русски: «${active.words[idx][0]}». `:'')+'👨 Одна буква открыта! −0,1 балла';render()}};\n$('nextButton').onclick=()=>{if(wrong>=MAX_TRIES){loadWord(idx);return}const next=active.words.findIndex((_,i)=>!completed(active).includes(i));if(next<0){map();return}loadWord(next)};\n$('start').onclick=map;$('toMap').onclick=map;$('toWelcome').onclick=()=>show('welcome');$('reset').onclick=()=>{if(confirm('Сбросить весь прогресс по 50 словам?')){progress={};scoreState={results:{},support:{}};save();saveScores();map()}};\ndocument.addEventListener('keydown',e=>{if($('game').classList.contains('hidden')||e.altKey||e.ctrlKey||e.metaKey||e.target instanceof HTMLInputElement)return;const ch=e.key.toLocaleUpperCase('ru-RU');if(alphabet.includes(ch))guess(ch)});\n</script><script>setTimeout(publishSeemScore,0);</script><script src=\"assets/viewport-fit.js\"></script></body></html>\n";
